// Baut aus der Meldung eine lesbare Zeile.
//
// Die Website schickt zwei Formen an denselben Webhook:
//   1. Ereignisse  (src/app/api/ereignis/route.ts)      -> ereignis, seite, referrer, firma, ort, ...
//   2. Tagesbericht (src/app/api/tagesbericht/route.ts)  -> bringt ein fertiges Feld `text` mit
//
// Wer weitere Ereignisse ergaenzt, traegt sie unten in TITEL ein — fehlt ein
// Eintrag, wird der technische Name angezeigt statt gar nichts.

const TITEL = {
  besuch: '👀 Besuch auf der Website',
  termin_geoeffnet: '📅 Terminseite geoeffnet',
  popup_geklickt: '🔵 Popup geklickt — will einen Call',
  telefon_geklickt: '📞 Telefonnummer geklickt',
  email_geklickt: '✉️ E-Mail-Adresse geklickt',
  selbstcheck_fertig: '✅ Selbstcheck abgeschlossen',
  tagesbericht: '📊 Tagesbericht',
};

const d = $input.first().json;

// Der Tagesbericht bringt seinen Text schon mit.
if (d.text) {
  return [{ json: { nachricht: d.text, ereignis: d.ereignis ?? 'tagesbericht', roh: d } }];
}

const zeilen = [TITEL[d.ereignis] ?? d.ereignis];

if (d.seite) zeilen.push(`Seite: ${d.seite}`);

// Firma und Ort kommen nur bei Besuchern mit Einwilligung an.
if (d.firma) zeilen.push(`Firma: ${d.firma}${d.ort ? ` (${d.ort})` : ''}`);
else if (d.ort) zeilen.push(`Ort: ${d.ort}`);

if (d.referrer) zeilen.push(`Kam von: ${d.referrer}`);

const kampagne = [d.utm_source, d.utm_medium, d.utm_campaign].filter(Boolean).join(' / ');
if (kampagne) zeilen.push(`Kampagne: ${kampagne}`);

if (d.zeitpunkt) {
  zeilen.push(
    new Date(d.zeitpunkt).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' })
  );
}

return [{ json: { nachricht: zeilen.join('\n'), ereignis: d.ereignis, roh: d } }];
